WITH base AS (SELECT *, ROUND(quantity * 0.85, 2) AS quantity_scaled FROM inventory WHERE product_id IN (8, 10)), with_windows AS (SELECT id, store_id, product_id, quantity, last_restock, quantity_scaled, LAG(quantity, 1) OVER (PARTITION BY product_id ORDER BY last_restock, id) AS prev_quantity, SUM(quantity_scaled) OVER (PARTITION BY store_id ORDER BY quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_quantity_scaled, FIRST_VALUE(quantity_scaled) IGNORE NULLS OVER (PARTITION BY store_id ORDER BY quantity_scaled, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_quantity_scaled FROM base), base_inventory AS (SELECT id, product_id, quantity, quantity_scaled, prev_quantity, running_quantity_scaled, first_known_quantity_scaled, DATE_TRUNC('year', last_restock) AS last_restock_period FROM with_windows WHERE last_restock > TO_DATE('2023-03-22')), prev_events AS (SELECT *, LAG(last_restock_period) OVER (PARTITION BY product_id ORDER BY last_restock_period, id) AS prev_last_restock_period FROM base_inventory), flagged AS (SELECT *, CASE WHEN prev_last_restock_period IS NULL OR last_restock_period > prev_last_restock_period + INTERVAL '14' DAY THEN 1 ELSE 0 END AS is_new_session FROM prev_events), sessionized AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY product_id ORDER BY last_restock_period, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM flagged), summary AS (SELECT DATE_TRUNC('YEAR', last_restock_period) AS year_start, CASE WHEN prev_quantity >= 239 THEN 'HIGH' ELSE 'LOW' END AS prev_quantity_tier, PERCENTILE_APPROX(running_quantity_scaled, ARRAY(0.25, 0.5, 0.75)) AS running_quantity_scaled_quartiles, PERCENTILE_APPROX(quantity, 0.95) AS quantity_p95 FROM sessionized GROUP BY year_start, prev_quantity_tier) SELECT year_start, prev_quantity_tier, quantity_p95 FROM summary ORDER BY quantity_p95 DESC, prev_quantity_tier
